<?php $delivery=$delivery??[];$rows=$delivery['goods']??[[]]; function deliveryValue(array $d,string $key): string{return htmlspecialchars((string)($d[$key]??''),ENT_QUOTES,'UTF-8');} ?>
<form id="<?= htmlspecialchars($formId,ENT_QUOTES,'UTF-8') ?>" data-delivery-form data-delivery-id="<?= (int)($delivery['id']??0) ?>" class="delivery-form"><div class="delivery-form-body"><div class="form-section"><div class="section-title"><h3>Destination</h3><p>Client, site et interlocuteur de réception.</p></div><div class="form-grid delivery-form-grid"><label class="field"><span>Client *</span><div><i data-lucide="building-2"></i><select name="client_id" required data-client-select><option value="">Sélectionner un client</option><?php foreach($clients as $client): ?><option value="<?= (int)$client['id'] ?>" <?= (int)($delivery['client_id']??0)===(int)$client['id']?'selected':'' ?>><?= htmlspecialchars($client['company_name'].' · '.$client['code'],ENT_QUOTES,'UTF-8') ?></option><?php endforeach; ?></select></div><small data-error="client_id"></small></label><label class="field"><span>Site de livraison *</span><div><i data-lucide="map-pin"></i><select name="client_site_id" required data-selected="<?= (int)($delivery['client_site_id']??0) ?>"><option value="">Sélectionner d’abord le client</option><?php if(!empty($delivery['client_site_id'])): ?><option value="<?= (int)$delivery['client_site_id'] ?>" selected><?= htmlspecialchars($delivery['site_name'].' · '.$delivery['site_city'],ENT_QUOTES,'UTF-8') ?></option><?php endif; ?></select></div><small data-error="client_site_id"></small></label><label class="field"><span>Contact</span><div><i data-lucide="contact"></i><select name="client_contact_id" data-selected="<?= (int)($delivery['client_contact_id']??0) ?>"><option value="">Aucun contact</option><?php if(!empty($delivery['client_contact_id'])): ?><option value="<?= (int)$delivery['client_contact_id'] ?>" selected><?= htmlspecialchars($delivery['contact_name'],ENT_QUOTES,'UTF-8') ?></option><?php endif; ?></select></div></label><label class="field"><span>Date prévue *</span><div><i data-lucide="calendar-clock"></i><input type="datetime-local" name="scheduled_at" value="<?= !empty($delivery['scheduled_at'])?date('Y-m-d\TH:i',strtotime($delivery['scheduled_at'])):'' ?>" required></div><small data-error="scheduled_at"></small></label><label class="field"><span>Priorité *</span><div><i data-lucide="flag"></i><select name="priority"><?php foreach(['Basse','Normale','Haute','Urgente'] as $priority): ?><option <?= ($delivery['priority']??'Normale')===$priority?'selected':'' ?>><?= $priority ?></option><?php endforeach; ?></select></div><small data-error="priority"></small></label></div></div>
<div class="form-section"><div class="section-title with-action"><div><h3>Marchandises</h3><p>Saisissez librement la désignation, la quantité et l’unité.</p></div><button type="button" class="button button-secondary" data-add-delivery-goods><i data-lucide="plus"></i> Ajouter une ligne</button></div><div class="delivery-goods-lines" data-delivery-goods><?php foreach($rows as $row): ?><div class="delivery-goods-row"><label class="field goods-description-field"><span>Désignation *</span><div><i data-lucide="package"></i><input type="text" maxlength="255" placeholder="Ex. Pipe Conductor" data-goods-field="description" value="<?= deliveryValue($row,'description_snapshot') ?>"></div></label><label class="field"><span>Quantité *</span><div><input type="number" step="0.001" min="0.001" data-goods-field="quantity" value="<?= deliveryValue($row,'quantity') ?>"></div></label><label class="field"><span>Unité *</span><div><input type="text" maxlength="30" placeholder="pièce, kg…" data-goods-field="unit" value="<?= deliveryValue($row,'unit') ?>"></div></label><label class="field"><span>Poids/unité (kg)</span><div><input type="number" step="0.001" min="0.001" placeholder="Facultatif" data-goods-field="unit_weight_kg" value="<?= deliveryValue($row,'unit_weight_kg') ?>"></div></label><span class="line-weight" data-line-weight>—</span><button type="button" class="remove-delivery-goods" aria-label="Supprimer"><i data-lucide="trash-2"></i></button></div><?php endforeach; ?></div><small class="form-error" data-error="goods"></small><div class="goods-total"><span>Poids total estimé</span><strong data-total-weight>0 kg</strong></div></div>
<div class="form-section"><div class="section-title"><h3>Affectation</h3><p>Le chauffeur et le véhicule sont requis avant préparation.</p></div><div class="form-grid delivery-form-grid"><label class="field"><span>Chauffeur</span><div><i data-lucide="contact-round"></i><select name="driver_id"><option value="">Non affecté</option><?php foreach($drivers as $driver): ?><option value="<?= (int)$driver['id'] ?>" <?= (int)($delivery['driver_id']??0)===(int)$driver['id']?'selected':'' ?>><?= htmlspecialchars($driver['first_name'].' '.$driver['last_name'].' · '.$driver['status'],ENT_QUOTES,'UTF-8') ?></option><?php endforeach; ?></select></div></label><label class="field"><span>Véhicule</span><div><i data-lucide="truck"></i><select name="vehicle_id"><option value="">Non affecté</option><?php foreach($vehicles as $vehicle): ?><option value="<?= (int)$vehicle['id'] ?>" data-driver="<?= (int)($vehicle['assigned_driver_id']??0) ?>" <?= (int)($delivery['vehicle_id']??0)===(int)$vehicle['id']?'selected':'' ?>><?= htmlspecialchars($vehicle['registration_number'].' · '.$vehicle['brand'].' '.$vehicle['model'].' · '.$vehicle['status'],ENT_QUOTES,'UTF-8') ?></option><?php endforeach; ?></select></div></label><label class="field full-span"><span>Observations</span><textarea name="observations" rows="3"><?= deliveryValue($delivery,'observations') ?></textarea></label></div></div></div><div class="modal-actions delivery-form-actions"><button type="button" class="button button-secondary" data-modal-close>Annuler</button><button type="submit" class="button button-primary"><i data-lucide="save"></i> <?= !empty($delivery['id'])?'Enregistrer les modifications':'Créer le brouillon' ?></button></div></form>
